const blocks = new Map();
function addText(id, text) {
  const b = blocks.get(id) ?? { text: '', citations: [] };
  blocks.set(id, { ...b, text: b.text + text });
}
function addCitation(id, citation) {
  const b = blocks.get(id);
  if (!b) throw new Error('Citation has no text block');
  blocks.set(id, { ...b, citations: [...b.citations, citation] });
}

